ALTER TABLE "movements" ADD CONSTRAINT "movements_type_check" CHECK ("movements"."type" in ('expense', 'income', 'transfer', 'exchange', 'adjustment'));--> statement-breakpoint
ALTER TABLE "movements" ADD CONSTRAINT "movements_amount_range_check" CHECK (("movements"."type" = 'adjustment' and "movements"."amount" <> 0 and abs("movements"."amount") <= 1000000000000000) or ("movements"."type" <> 'adjustment' and "movements"."amount" between 1 and 1000000000000000));--> statement-breakpoint
ALTER TABLE "movements" ADD CONSTRAINT "movements_shape_check" CHECK (("movements"."type" in ('expense', 'income') and "movements"."category_id" is not null and "movements"."rate" is not null and "movements"."rate_source" is not null and "movements"."rate_source" in ('automatic', 'manual') and "movements"."destination_account_id" is null and "movements"."destination_amount" is null) or ("movements"."type" = 'transfer' and "movements"."category_id" is null and "movements"."destination_account_id" is not null and "movements"."destination_amount" is not null and "movements"."destination_amount" = "movements"."amount" and "movements"."rate" is null and "movements"."rate_source" is null and "movements"."rate_type" is null) or ("movements"."type" = 'exchange' and "movements"."category_id" is null and "movements"."destination_account_id" is not null and "movements"."destination_amount" is not null and "movements"."rate" is not null and "movements"."rate_source" is not null and "movements"."rate_source" = 'implied' and "movements"."rate_type" is null) or ("movements"."type" = 'adjustment' and "movements"."category_id" is null and "movements"."rate" is null and "movements"."rate_source" is null and "movements"."rate_type" is null and "movements"."destination_account_id" is null and "movements"."destination_amount" is null));